            String path = st.nextToken();
            String value = st.nextToken();
            entries.add(new String[]{path, value});
        }
        int q = Integer.parseInt(st.nextToken());
        List<String> queries = new ArrayList<>();
        for (int i = 0; i < q; i++) queries.add(st.nextToken());
