def gen(rng):
    pool_small = ['a', 'b', 'c', 'cell', 'home', 'x', 'y', 'k1']
    pool_big = ['k%d' % i for i in range(9)]
    vchars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJ0123456789+().-_'

    def rval():
        v = ''.join(rng.choice(vchars) for _ in range(rng.randint(1, 8)))
        return v if v != 'null' else 'nul'

    def build(count, pool, maxdepth):
        tree = {}
        entries = []
        attempts = 0
        while len(entries) < count and attempts < count * 30:
            attempts += 1
            depth = rng.randint(1, maxdepth)
            keys = [rng.choice(pool) for _ in range(depth)]
            node = tree
            bad = False
            for i, k in enumerate(keys):
                last = i == len(keys) - 1
                if last:
                    if k in node:
                        bad = True
                    break
                if k in node:
                    if isinstance(node[k], str):
                        bad = True
                        break
                    node = node[k]
                else:
                    # create lazily only if path accepted; check later
                    node = None
                    break
            if bad:
                continue
            # insert for real
            node = tree
            for i, k in enumerate(keys):
                if i == len(keys) - 1:
                    node[k] = rval()
                else:
                    node = node.setdefault(k, {})
            entries.append(keys)
        return tree, entries

    def ser(x):
        if isinstance(x, str):
            return x
        return '{' + ','.join(k + ':' + ser(v) for k, v in x.items()) + '}'

    def run(tree, segs):
        res = []

        def walk(node, i):
            if i == len(segs):
                res.append(node)
                return
            if not isinstance(node, dict):
                return
            if segs[i] == '*':
                for c in node.values():
                    walk(c, i + 1)
            elif segs[i] in node:
                walk(node[segs[i]], i + 1)

        walk(tree, 0)
        return res

    def leaves(tree, prefix=()):
        out = []
        for k, v in tree.items():
            if isinstance(v, str):
                out.append((prefix + (k,), v))
            else:
                out += leaves(v, prefix + (k,))
        return out

    def make_case(count, pool, maxdepth, nq, limit_chars):
        tree, entries = build(count, pool, maxdepth)
        lv = leaves(tree)
        # entry order: reconstruct from insertion by re-walking in generation order
        lines = []
        for keys in entries:
            node = tree
            for k in keys:
                node = node[k]
            lines.append('.' + '.'.join(keys) + ' ' + node)
        queries = []
        tries = 0
        while len(queries) < nq and tries < nq * 50:
            tries += 1
            kind = rng.randint(0, 5)
            keys, _ = rng.choice(lv)
            keys = list(keys)
            if kind == 0:
                segs = keys
            elif kind == 1:
                segs = keys[:rng.randint(1, len(keys))]
            elif kind == 2:
                segs = [('*' if rng.random() < 0.4 else k) for k in keys]
            elif kind == 3:
                segs = [('*' if rng.random() < 0.4 else k) for k in keys[:rng.randint(1, len(keys))]]
            elif kind == 4:
                segs = list(keys)
                segs[rng.randrange(len(segs))] = rng.choice(['zz', 'nokey', 'k1'])
            else:
                segs = keys + [rng.choice(pool + ['*'])]
            res = run(tree, segs)
            text = '[' + ','.join(ser(r) for r in res) + ']' if '*' in segs else (ser(res[0]) if res else 'null')
            if len(text) > limit_chars:
                continue
            queries.append('.' + '.'.join(segs))
        return lines, queries

    def fmt(lines, queries):
        return f"{len(lines)}\n" + "\n".join(lines) + f"\n{len(queries)}\n" + "\n".join(queries)

    tests = []
    base = [
        ".fname masked_first\n.lname masked_last\n.contacts.cell +1(999).999.9999\n.contacts.home +1(333).333.3333\n.contacts.cells.cell1 121211".split("\n"),
    ]
    tests.append(fmt(base[0], ['.contacts.cell', '.fname', '.contacts.work', '.*.cell', '.contacts', '.contacts.*', '.*', '.*.*', '.contacts.cells.*']))
    tests.append(fmt(['.a x'], ['.a', '.b', '.a.b', '.*', '.*.*']))
    tests.append(fmt(['.a.b.c v', '.a.b.d w', '.a.e z'], ['.a', '.a.b', '.a.*', '.*.*.*', '.*.b.*', '.a.b.c.d', '.*.e']))
    tests.append(fmt(['.p.x 1', '.q.x 2', '.p.y 3', '.q.y 4', '.r 5'], ['.*.x', '.*.y', '.*', '.p', '.q', '.*.*']))
    for _ in range(55):
        cnt = rng.randint(1, 10)
        lines, queries = make_case(cnt, pool_small, rng.randint(1, 4), rng.randint(1, 6), 150)
        if queries:
